const item = $input.first().json;

return [{
  json: item.body
}];

// n8n Code node — Mode: "Run Once for All Items"
// Merges the 3 exclusion nodes by row_number

const jobItems   = $('FILTER ON: FINAL JOB ROLE EXCL').all().map(i => i.json);
const catItems   = $('FINAL CATEGORIZATION EXCLUSION').all().map(i => i.json);
const eventItems = $('FINAL PREVIOUS EVENT EXCLUSION').all().map(i => i.json);

// Index each node's data by row_number
const indexBy = (items) => {
  const map = new Map();
  for (const item of items) map.set(Number(item.row_number), item);
  return map;
};

const jobMap   = indexBy(jobItems);
const catMap   = indexBy(catItems);
const eventMap = indexBy(eventItems);

// null / undefined -> "" (blank)
const clean = (v) => (v === null || v === undefined ? '' : v);
const isX   = (v) => String(clean(v)).trim().toLowerCase() === 'x';

// Union of all row numbers (some rows only exist in some nodes, e.g. row 17)
const rowNumbers = [...new Set([
  ...jobMap.keys(),
  ...catMap.keys(),
  ...eventMap.keys(),
])].sort((a, b) => a - b);

const output = rowNumbers.map((row) => {
  const job   = jobMap.get(row)   || {};
  const cat   = catMap.get(row)   || {};
  const event = eventMap.get(row) || {};

  // Job role match wins; otherwise fall back to categorization match; otherwise blank
  let jobAndCategorization = '';
  if (isX(job.job_role_exclusion_match)) {
    jobAndCategorization = 'x';
  } else if (isX(cat.initial_categorization_exclusion_match)) {
    jobAndCategorization = 'x';
  }

  return {
    json: {
      row_number: row,
      initial_categorization: clean(cat.initial_categorization),
      job_and_categorization_exclusion_match: jobAndCategorization,
      tom_exclusion_match:   clean(event.tom_exclusion_match),
      ines_exclusion_match:  clean(event.ines_exclusion_match),
      luke_exclusion_match:  clean(event.luke_exclusion_match),
      rica_exclusion_match:  clean(event.rica_exclusion_match),
      rohan_exclusion_match: clean(event.rohan_exclusion_match),
    },
  };
});

return output;

