// 1. Data from the previous-previous node
const exclusionData = $('GET: AEML - PREVIOUS EXCLUSIONS').all().map(item => item.json);

// 2. Data from the immediately previous node
const previousData = $input.all().map(item => item.json);

const excluders = ['Tom', 'Ines', 'Luke', 'Rica', 'Rohan'];

// Normalize names so casing/spacing differences don't break the match
const normalize = (name) => (name || '').trim().toLowerCase();

const results = previousData.map(row => {
  const match = exclusionData.find(ex => normalize(ex.name) === normalize(row.name));

  const matchName = !!match;

  const output = {
    row_number: row.row_number,
    name: row.name,
    match_name: matchName
  };

  // Add one field per excluder, only set when there's an "X"
  excluders.forEach(person => {
    const val = match ? match[person] : null;
    output[person] = (val && val.toString().trim().toUpperCase() === 'X') ? 'X' : null;
  });

  return { json: output };
});

return results;

