const loopItems = $('CATEGORIZATION: LOOP').all();
const previousItems = $input.all();

return loopItems.map((loopItem, index) => {
  const previousItem = previousItems[index];
  return {
    json: {
      row_number: loopItem.json.row_number,
      initial_categorization: previousItem.json.output.category
    }
  };
});

// Get all items from the previous node
const previousItems = $input.all();

return previousItems;

// Get data from both referenced nodes
const exclusionList = $('GET: AEML - CATEGORIZATION EXCLUSION').all();
const previousNodeData = $input.all();

// Build a Set of excluded categorization values for fast lookup
const exclusionSet = new Set(
  exclusionList.map(item => item.json.categorization)
);

// Map over the previous node's data and add the match field
const output = previousNodeData.map(item => {
  const initial_categorization = item.json.initial_categorization;
  const isMatch = exclusionSet.has(initial_categorization);

  return {
    json: {
      row_number: item.json.row_number,
      initial_categorization: initial_categorization,
      initial_categorization_exclusion_match: isMatch
    }
  };
});

return output;

// Exclusion list of job roles comes from the immediately previous node
const exclusionItems = $input.all();

// Pull the original user sheet data from the "RETRIEVE USER SHEET PROVIDED" node
const userSheetItems = $('RETRIEVE USER SHEET PROVIDED V1').all();

// Build a normalized array of exclusion job roles (trimmed, lowercased, deduped)
const exclusionRoles = [
  ...new Set(
    exclusionItems
      .map(item => (item.json.job_role || '').trim().toLowerCase())
      .filter(role => role !== '')
  )
];

// Walk through the user sheet and flag partial matches
return userSheetItems.map(item => {
  const jobRole = (item.json.job_role || '').trim().toLowerCase();

  let isMatch = false;
  if (jobRole !== '') {
    isMatch = exclusionRoles.some(exclRole => jobRole.includes(exclRole));
  }

  return {
    json: {
      ...item.json,
      job_role_exclusion_match: isMatch
    }
  };
});

// Exclusion list of job roles comes from the immediately previous node
const exclusionItems = $input.all();

// Pull the original user sheet data from the "FILTERED: RETRIEVE USER SHEET PROVIDED" node
const userSheetItems = $('RETRIEVE USER SHEET PROVIDED V1').all();

// Pull the job role inclusion master list
const inclusionItems = $('FILTERED: GET: AEML - JOB ROLE INCLUSION').all();

// Build a normalized array of exclusion job roles (trimmed, lowercased, deduped)
const exclusionRoles = [
  ...new Set(
    exclusionItems
      .map(item => (item.json.job_role || '').trim().toLowerCase())
      .filter(role => role !== '')
  )
];

// Build a normalized array of inclusion job roles (trimmed, lowercased, deduped)
const inclusionRoles = [
  ...new Set(
    inclusionItems
      .map(item => (item.json.job_role || '').trim().toLowerCase())
      .filter(role => role !== '')
  )
];

// Walk through the user sheet and flag partial matches
return userSheetItems.map(item => {
  const jobRole = (item.json.job_role || '').trim().toLowerCase();

  let isMatch = false;
  if (jobRole !== '') {
    isMatch = exclusionRoles.some(exclRole => jobRole.includes(exclRole));
  }

  // Inclusion master list always overrides exclusion, even on a match
  let isIncluded = false;
  if (jobRole !== '') {
    isIncluded = inclusionRoles.some(inclRole => jobRole.includes(inclRole));
  }

  if (isIncluded) {
    isMatch = false;
  }

  return {
    json: {
      ...item.json,
      job_role_exclusion_match: isMatch
    }
  };
});
